import pathlib,json,datetime,hashlib,numpy as np
R=pathlib.Path(__file__).resolve().parent
selftest=json.loads((R/'results/contact_collection_selfcheck.json').read_text());assert selftest['passed']
diag=json.loads((R/'results/P2_P3_diagnostic_rerun.json').read_text());assert len(diag)==5
rule={'stage':'P3','kind':'uniform action amplitude damping','action_scale':.5,'trigger':'all steps 1..200; no ground truth or future information','duration_steps':200,'applications_per_episode':1,'policy_calls_per_episode':200,'control_steps':200,'changed_components':'xyz policy action only before official wrapper; OSC and physics unchanged','claims':'Command amplitude reduction, not guaranteed measured physical speed bound. No directed edge oracle and no P2 recovery. B0/B1 two arms only.'}
(R/'intervention.json').write_text(json.dumps(rule,indent=2))
scenes=[s for s in json.loads((R/'results/scenes_all.json').read_text()) if 8<=s['group']<12 and s['condition']=='6_crowded'];assignment=[dict(s,arm=arm) for arm in ['B0','B1'] for s in scenes];rng=np.random.RandomState(2611124);assignment=[assignment[i] for i in rng.permutation(len(assignment))]
for i,s in enumerate(assignment):s['slot']=i
(R/'results/validation_assignment.json').write_text(json.dumps(assignment,indent=2))
freeze={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'stage':'P3-B independent complete-task validation','priority_decision_before_intervention_results':True,'choice_reason':'Four old stalls did not recur in one fixed-case rerun; three new falls have pre-crossing peak object speeds 0.396..0.759 m/s. Contact counterparts remain unknown. Test one simple, nondirected control baseline rather than claim a targeted cause. P2-B has no sufficiently localized explanation and remains unexecuted.','prior_data_role':'old trajectories and fixed reruns discovery/calibration only','groups':[8,9,10,11],'new_scene_seed':202611123,'arms':['B0','B1'],'episodes_per_arm':4,'scene_assignment_seed':2611124,'policy_sampling_seed':951126,'time':200,'horizon':5,'diffusion_steps':100,'primary_metric':'end-point mean object XY strict <.04 fraction; falls and progress jointly evaluated','randomization':'Each new matched scene instantiated once per arm in isolated vector environments; assignment to policy RNG batch slots permuted before run. Same seed does not imply restored states. Single simultaneously sampled batch, paired scene analysis.','data_role':'independent validation, not used for choosing damping parameter','measurement_change':selftest,'stop_budget_gpu_seconds':2300,'global_cap_gpu_seconds':7200,'memory_stop_mib':11264,'source_and_scenes_sha256':{}}
for n in ['evaluate_validation.py','prepare.py','guard.py','launch_validation.py','run_job_validation.sh','results/scenes_all.json','results/identity.json','intervention.json','results/validation_assignment.json']:
 freeze['source_and_scenes_sha256'][n]=hashlib.sha256((R/n).read_bytes()).hexdigest()
(R/'freeze_validation.json').write_text(json.dumps(freeze,indent=2))
print('FROZEN_P3_8',[(s['slot'],s['group'],s['arm']) for s in assignment])
